package offline;

import java.io.ByteArrayOutputStream;

/** Decoded frame together with everything needed to rebuild its canonical encoding. */
public final class Frame {

    public int type;

    // stream / crypto / generic identifiers
    public long id;
    public long errorCode;
    public long finalSize;
    public long offset;
    public long length;
    public boolean hasOffset;
    public boolean hasLength;
    public boolean fin;
    public byte[] data;

    // ACK frames
    public long ackLargest;
    public long ackDelay;
    public long ackFirst;
    public long[] ackPairs;
    public long[] ecn;

    // connection id frames
    public long sequence;
    public long retirePriorTo;
    public long cidLength;
    public byte[] cid;
    public byte[] token;

    // connection close frames
    public long triggerType;
    public byte[] reason;

    public Frame(int type) {
        this.type = type;
    }

    private static void writeVar(ByteArrayOutputStream out, long value) {
        byte[] encoded = QuicVarint.encode(value);
        out.write(encoded, 0, encoded.length);
    }

    /** Canonical encoding of the frame; every varint is minimal, opaque data is preserved. */
    public byte[] canonical() {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.write(type);
        switch (type) {
            case 0x00:
            case 0x01:
                break;
            case 0x02:
            case 0x03:
                writeVar(out, ackLargest);
                writeVar(out, ackDelay);
                writeVar(out, ackPairs.length / 2);
                writeVar(out, ackFirst);
                for (long pair : ackPairs) {
                    writeVar(out, pair);
                }
                if (type == 0x03 && ecn != null) {
                    for (long counter : ecn) {
                        writeVar(out, counter);
                    }
                }
                break;
            case 0x04:
                writeVar(out, id);
                writeVar(out, errorCode);
                writeVar(out, finalSize);
                break;
            case 0x05:
                writeVar(out, id);
                writeVar(out, errorCode);
                break;
            case 0x06:
                writeVar(out, offset);
                writeVar(out, length);
                out.write(data, 0, data.length);
                break;
            case 0x08:
            case 0x09:
            case 0x0a:
            case 0x0b:
            case 0x0c:
            case 0x0d:
            case 0x0e:
            case 0x0f:
                writeVar(out, id);
                if (hasOffset) {
                    writeVar(out, offset);
                }
                if (hasLength) {
                    writeVar(out, length);
                }
                out.write(data, 0, data.length);
                break;
            case 0x10:
                writeVar(out, finalSize);
                break;
            case 0x11:
                writeVar(out, id);
                writeVar(out, finalSize);
                break;
            case 0x12:
            case 0x13:
            case 0x14:
            case 0x16:
            case 0x17:
                writeVar(out, finalSize);
                break;
            case 0x15:
                writeVar(out, id);
                writeVar(out, finalSize);
                break;
            case 0x18:
                writeVar(out, sequence);
                writeVar(out, retirePriorTo);
                out.write((int) cidLength);
                out.write(cid, 0, cid.length);
                out.write(token, 0, token.length);
                break;
            case 0x19:
                writeVar(out, sequence);
                break;
            case 0x1a:
            case 0x1b:
                out.write(data, 0, data.length);
                break;
            case 0x1c:
                writeVar(out, errorCode);
                writeVar(out, triggerType);
                writeVar(out, reason.length);
                out.write(reason, 0, reason.length);
                break;
            case 0x1d:
                writeVar(out, errorCode);
                writeVar(out, reason.length);
                out.write(reason, 0, reason.length);
                break;
            case 0x30:
                out.write(data, 0, data.length);
                break;
            case 0x31:
                writeVar(out, length);
                out.write(data, 0, data.length);
                break;
            default:
                throw new IllegalStateException("unsupported frame type " + type);
        }
        return out.toByteArray();
    }
}
