package offline;

/** Semantic or encoding failure of a frame; aborts the current packet transaction. */
public final class FrameError extends Exception {

    private static final long serialVersionUID = 1L;

    public final String code;
    public final int offset;

    public FrameError(String code, int offset) {
        super(code + " at " + offset);
        this.code = code;
        this.offset = offset;
    }
}
